$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$splitPlanner = Decode ""
$splitApi = Decode ""

$plannerPath = Join-Path $root "lib\multi-provider-split-plan.ts"
$apiPath = Join-Path $root "app\api\brain\market-split-plan\[id]\route.ts"
$livePath = Join-Path $root "lib\multi-slot-live-coverage.ts"

if (-not (Test-Path -LiteralPath $livePath)) {
    throw "12.99 : live coverage 12.95 introuvable."
}

$live = [System.IO.File]::ReadAllText($livePath)

if (-not $live.Contains("KLYX_MULTI_SLOT_LIVE_COVERAGE_12_95")) {
    throw "12.99 : mauvais helper live coverage."
}

New-Item -ItemType Directory -Force -Path (Split-Path -Parent $apiPath) | Out-Null

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

if (Test-Path -LiteralPath $plannerPath) {
    Copy-Item -LiteralPath $plannerPath -Destination ($plannerPath + ".bak-12-99-" + $timestamp) -Force
}

if (Test-Path -LiteralPath $apiPath) {
    Copy-Item -LiteralPath $apiPath -Destination ($apiPath + ".bak-12-99-" + $timestamp) -Force
}

[System.IO.File]::WriteAllText($plannerPath, $splitPlanner, $utf8)
[System.IO.File]::WriteAllText($apiPath, $splitApi, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 12.99 APPLIQUE"
Write-Host "======================================"
Write-Host "1 prestataire N/N : PRIORITAIRE"
Write-Host "Fallback 2 prestataires : OK"
Write-Host "Fallback 3 prestataires : OK"
Write-Host "Disponibilites live : OUI"
Write-Host "Conflits bookings : OUI"
Write-Host "Attribution slots : CALCULEE"
Write-Host "Selection automatique : NON"
Write-Host "Booking automatique : NON"
Write-Host "Paiement automatique : NON"
Write-Host "======================================"
